baseCss:
.aha-mcards{
  container:aha-mcards / inline-size;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-mcards *{box-sizing:border-box}
:where(.aha-mcard) h3,:where(.aha-mcard) p,:where(.aha-mcard) blockquote,:where(.aha-mcard) figure,figure:where(.aha-mcard){margin:0}
:where(.aha-mcard) blockquote{padding:0}
:where(.aha-mcards) ol{margin:0;padding:0}
.aha-mcards__grid{
  display:grid;grid-template-columns:repeat(3,minmax(0,1fr));
  gap:var(--aha-space-32);
  max-width:72rem;margin:0 auto;
  padding:var(--aha-space-64) var(--aha-space-24);
  list-style:none;
}
.aha-mcard{
  position:relative;
  display:flex;flex-direction:column;
  height:100%;
  background:var(--aha-bg-container);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
  border:1px solid var(--aha-border-default);
  border-radius:var(--aha-radius-marketing);
  overflow:hidden;
}
.aha-mcard *{box-sizing:border-box}
.aha-mcard__media{
  display:flex;align-items:center;justify-content:center;
  width:100%;
  background:var(--aha-bg-container-secondary);
  color:var(--aha-icon-muted);
  overflow:hidden;
}
.aha-mcard__media--16x9{aspect-ratio:16 / 9}
.aha-mcard__media--3x2{aspect-ratio:3 / 2}
.aha-mcard__media img{display:block;width:100%;height:100%;object-fit:cover}
.aha-mcard__body{
  display:flex;flex-direction:column;flex:1;
  gap:var(--aha-space-12);
  padding:var(--aha-space-24);
}
.aha-mcard__eyebrow{
  font-size:var(--aha-size-sm);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-subheadings);
  text-transform:uppercase;
  color:var(--aha-color-primary);
}
.aha-mcard__title{
  font-size:var(--aha-size-xl);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-text-default);
}
.aha-mcard__text{
  font-size:var(--aha-size-l);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-mcard__meta{
  font-size:var(--aha-size-default);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-tertiary);
}
.aha-mcard__more{
  display:inline-flex;align-items:center;gap:var(--aha-space-8);
  margin-top:auto;
  font-size:var(--aha-size-default);
  font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-default);
}
.aha-mcard__link{color:inherit;text-decoration:none}
.aha-mcard__link::after{content:"";position:absolute;inset:0}
.aha-mcard__link:focus-visible{outline:none}
.aha-mcard:has(.aha-mcard__link:focus-visible){
  outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);
}
.aha-mcard--linked{
  transition:transform var(--aha-motion-mid) var(--aha-ease-out),box-shadow var(--aha-motion-mid) var(--aha-ease-out),border-color var(--aha-motion-mid) var(--aha-ease-out);
}
.aha-mcard--linked:hover{
  transform:translateY(calc(-1 * var(--aha-space-4)));
  border-color:var(--aha-border-hover);
  box-shadow:0 var(--aha-space-12) var(--aha-space-24) var(--aha-ink-a10);
}
.aha-mcard--linked:hover .aha-mcard__more{color:var(--aha-text-link-hover)}
@media (prefers-reduced-motion:reduce){
  .aha-mcard--linked{transition:none}
  .aha-mcard--linked:hover{transform:none}
}
@container aha-mcards (max-width:991px){
  .aha-mcards__grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-24)}
}
@container aha-mcards (max-width:767px){
  .aha-mcards__grid{grid-template-columns:minmax(0,1fr);padding:var(--aha-space-48) var(--aha-space-24)}
}
@container aha-mcards (max-width:479px){
  .aha-mcards__grid{padding:var(--aha-space-32) var(--aha-space-16)}
  .aha-mcard__body{padding:var(--aha-space-20)}
}
